import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/memory.DZ7s1dmm.png",t="/ascendc.github.io/assets/simt_ub.CycysjF4.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMT编程","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/ai_core_simt_programming"},{"text":"内存层级","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/memory_hierarchy"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simt_programming/memory_hierarchy.md","filePath":"guide/programming_guide/programming_model/ai_core_simt_programming/memory_hierarchy.md","outlineHeaders":[{"level":2,"title":"全局内存（Global Memory）","slug":"全局内存（Global-Memory）","link":"#全局内存（Global-Memory）"},{"level":2,"title":"共享内存","slug":"共享内存","link":"#共享内存"},{"level":3,"title":"共享内存大小的限制","slug":"共享内存大小的限制","link":"#共享内存大小的限制"},{"level":2,"title":"栈空间","slug":"栈空间","link":"#栈空间"},{"level":3,"title":"GM上的SIMT栈空间","slug":"GM上的SIMT栈空间","link":"#GM上的SIMT栈空间"},{"level":3,"title":"UB上的SIMT函数调用中转栈空间","slug":"UB上的SIMT函数调用中转栈空间","link":"#UB上的SIMT函数调用中转栈空间"},{"level":2,"title":"寄存器","slug":"寄存器","link":"#寄存器"},{"level":3,"title":"通用寄存器","slug":"通用寄存器","link":"#通用寄存器"},{"level":3,"title":"传参寄存器","slug":"传参寄存器","link":"#传参寄存器"},{"level":2,"title":"编程建议","slug":"编程建议","link":"#编程建议"}],"lastUpdated":1787798726000}'),e={name:"guide/programming_guide/programming_model/ai_core_simt_programming/memory_hierarchy.md"};function i(o,s,r,d,h,g){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>内存层级<span id="ZH-CN_TOPIC_0000002523359048"></span></h1><p>SIMT线程可访问多种内存空间。下表汇总了SIMT编程中常见内存类型的作用域及其生命周期。</p><table><thead><tr><th>内存类型</th><th>线程作用域</th><th>生命周期</th><th>物理位置</th></tr></thead><tbody><tr><td>全局内存</td><td>Grid</td><td>应用程序</td><td>Device</td></tr><tr><td>共享内存</td><td>Block</td><td>核函数（Kernel）</td><td>Vector Core</td></tr><tr><td>栈空间</td><td>Thread</td><td>核函数（Kernel）</td><td>Global Memory</td></tr><tr><td>寄存器</td><td>Thread</td><td>核函数（Kernel）</td><td>Vector Core</td></tr></tbody></table><ul><li>全局内存是所有线程均可直接访问的内存资源，即Global Memory；</li><li>共享内存是线程块内所有线程共享的内存，位于Unified Buffer（UB），生命周期和线程块一致。</li><li>每个线程拥有独立的栈空间，主要用于存放线程私有临时数据。</li><li>每个线程拥有独立的寄存器，用于存储局部变量。</li><li>在访问性能方面，寄存器具有最高的访问速度；共享内存的访问效率优于全局内存。</li></ul><p>内存层级如下图所示：<br><img src="'+c+`" width="50%"></p><h2 id="全局内存（Global-Memory）">全局内存（Global Memory）<span id="section8946131492119"></span><a class="header-anchor" href="#全局内存（Global-Memory）">​</a></h2><p>Device侧的全局内存是整个Grid中所有线程均可访问的内存空间。全局内存具有持久性：通过全局内存分配的空间及其存储的数据将持续保留，直到该内存空间被释放或应用程序终止。用户需在核函数（Kernel）启动前通过Runtime API完成全局内存的分配与初始化，核函数（Kernel）执行期间SIMT每个线程均可读写全局内存，执行完毕后可将结果拷贝回Host。有关Runtime API的更多信息与细节，可以参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>。</p><p>运行在Device侧的核函数（Kernel）可以通过指针直接访问全局内存。下述代码展示了全局内存的简易示例。数组x、y、z均存储于全局内存中，通过以下核函数（Kernel）实现每个线程对全局内存的访问和存储。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// Calculate global thread ID</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// Maps to the row index of output tensor</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">z</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="p">}</span>
</code></pre></div><h2 id="共享内存">共享内存<span id="section66329146410"></span><a class="header-anchor" href="#共享内存">​</a></h2><p>共享内存是同一线程块内所有线程均可访问的内存空间，位于每个Vector Core（AIV）内的UB。与全局内存相比，共享内存的容量较小，但具有更高的带宽和更低的访问延迟，可视为内核执行期间由用户管理的高速缓存资源。</p><p>用户可通过动态或者静态方式申请共享内存。</p><ol><li><p>静态申请：分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改，开发者通过数组分配申请使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">static_buf</span><span class="p">[</span><span class="mi">1024</span><span class="p">];</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><p>默认情况下，申请到的静态内存首地址按照数据类型对齐，也支持用户使用<code>__align__(N)</code>手动指定对齐。</p></li><li><p>动态申请：用户需要通过&lt;&lt;&lt;&gt;&gt;&gt;中参数<a href="kernel_function.html#li12421238101815">dyn_ubuf_size</a>指定动态内存的空间大小，其大小在运行期确定，SIMT编程中可通过以下方式申请使用动态内存。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Device侧：声明动态共享内存</span>
<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">dynamic_buf</span><span class="p">[];</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>

<span class="c1">// Host侧：通过&lt;&lt;&lt;&gt;&gt;&gt;中的第三个参数指定动态共享内存大小</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">main</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="o">*</span><span class="n">argv</span><span class="p">[])</span>
<span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">char</span><span class="p">);</span>
<span class="w">    </span><span class="n">add_custom</span><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(...);</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div></li></ol><h3 id="共享内存大小的限制">共享内存大小的限制<a class="header-anchor" href="#共享内存大小的限制">​</a></h3><p>如下图所示，UB内存空间总大小为256KB。默认编译模式下，UB按功能划分为四个主要区域，从低地址到高地址依次为静态内存、动态内存、预留空间和Data Cache。由于这四类区域共享同一块UB内存，因此用户在配置共享内存大小时，应确保为Data Cache保留足够的空间（至少32KB），避免因可用空间不足导致校验报错。</p><p><img src="`+t+`" alt></p><p>具体结构如下：</p><ol><li><p>静态内存和动态内存对应用户静态、动态申请方式分配的内存。</p></li><li><p>预留空间：编译器和Ascend C预留空间，大小固定为8KB。</p></li><li><p>Data Cache：SIMT专有的Data Cache空间，用于SIMT线程访问全局内存时的数据缓存，Data Cache的空间可配置范围为<strong>最小32KB、最大128KB</strong>，实际内存大小受用户配置的静态和动态内存大小影响，具体计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Data Cache空间大小 = min(UB总大小（256KB） - 静态内存 - 动态内存 - 预留空间（8KB）, 128KB)
</code></pre></div><p>Data Cache空间上限为<strong>128KB</strong>，即使静态与动态内存申请较少，Data Cache实际分配大小也不会超出该上限。</p></li></ol><p>由于Data Cache、预留空间与用户申请的UB内存共用同一块UB，因此开发者无法使用全部UB空间，应确保实际访问范围不超过已申请的静态内存和动态内存大小。</p><p>静态内存和动态内存的声明或配置限定了用户使用UB内存的有效范围。若用户配置的内存大小不足，甚至未申请内存即直接访问UB地址，访问地址可能越过用户动、静态内存边界并落入Data Cache区域。由于Data Cache容量由UB总量扣除静态内存、动态内存和预留空间后确定，所以用户共享内存配置偏小会扩大可分配给Data Cache的剩余空间。当程序执行越过已申请的动、静态内存边界，发生越界写入行为时，未必立即表现为内存分配失败，但可能破坏SIMT全局内存访问的数据缓存，导致计算结果不稳定或算子精度异常。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>用户可选择禁用预留空间，禁用方法为：编译时增加<a href="../../compilation_and_execution/operator_compilation/ai_core_operator_compilation.html#ZH-CN_TOPIC_0000002462746461">--cce-disable-vf-stack-reserved-ubuf</a>选项。开启该选项后，编译器不再预留该部分UB空间，该空间可作为普通UB空间使用，Data Cache空间可按如下公式估算：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Data Cache空间大小 = min(UB总大小（256KB） - 静态内存 - 动态内存, 128KB)
</code></pre></div><p>使用该选项时，仍需保证Data Cache空间不小于32KB，且Data Cache空间上限仍为128KB。开启该选项后，编译器将无法使用预留UB空间作为寄存器溢出的缓存空间，开发者需保证不会发生寄存器溢出。</p></div><h2 id="栈空间">栈空间<a class="header-anchor" href="#栈空间">​</a></h2><p>SIMT编程中的栈空间由编译器管理，生命周期与核函数（Kernel）一致，包括以下两部分：</p><ul><li>位于Global Memory（GM）上的SIMT栈空间。</li><li>位于UB上用于SIMT函数调用参数传递的中转栈空间(UB上8KB预留空间的一部分)。</li></ul><p>下文分别说明这两类栈空间。</p><h3 id="GM上的SIMT栈空间">GM上的SIMT栈空间<a class="header-anchor" href="#GM上的SIMT栈空间">​</a></h3><p>GM上的SIMT栈空间用于保存线程私有运行时状态，按用途分为SIMT通用栈空间和SIMT Divergence（分支）栈空间。</p><ul><li><strong>SIMT通用栈空间</strong><br> 用于存放线程私有临时数据，包括函数调用产生的临时数据、无法完全分配到寄存器的局部对象、<a href="#%E5%AF%84%E5%AD%98%E5%99%A8">寄存器</a>溢出（register spill）产生的临时数据等。每个线程的SIMT通用栈空间默认大小为1152Byte，由于位于Global Memory，其访问延迟高于寄存器访问。局部变量较多、函数调用链较深、使用较大的线程私有数组，或最大线程数配置过大导致每个线程可用寄存器不足时，栈空间占用会相应增加，严重时可能引发栈溢出。</li><li><strong>SIMT Divergence栈空间</strong><br> 用于存放SIMT分支发散场景下的程序计数器（PC，Program Counter）和活动掩码（Active Mask）。Warp内线程共享一个SIMT Divergence栈空间，每个Warp的栈空间默认大小为1024Byte。分支发散越频繁、控制流越复杂，该栈空间占用越高，严重时可能引发栈溢出。</li></ul><p>开发者可通过<code>--cce-res-usage</code>编译选项查看核函数（Kernel）的栈空间使用情况。若栈空间占用较高，应优先减少线程私有临时变量、控制调试打印的数据量、简化函数调用链并优化分支发散逻辑，以减少不必要的Global Memory访问。若业务确需调整栈空间大小，可通过<code>aclInit()</code>接口加载的配置文件进行设置：配置项<code>simt_stack_size</code>用于设置每个线程的SIMT通用栈空间大小，<code>simt_divergence_stack_size</code>用于设置SIMT Divergence栈空间大小，单位均为Byte。配置示例如下，更多说明请参考<a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/latest/API/runtimeapi/aclcppdevg_03_0022.html">aclInit()接口配置说明</a>中的“SIMT算子栈空间大小配置示例”。</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">{</span>
<span class="w">  </span><span class="nt">&quot;StackSize&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;simt_stack_size&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">1024</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;simt_divergence_stack_size&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">512</span>
<span class="w">  </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h3 id="UB上的SIMT函数调用中转栈空间">UB上的SIMT函数调用中转栈空间<a class="header-anchor" href="#UB上的SIMT函数调用中转栈空间">​</a></h3><p>如上文<a href="#%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%E5%A4%A7%E5%B0%8F%E7%9A%84%E9%99%90%E5%88%B6">共享内存大小的限制</a>所述，UB中有8KB大小的预留空间，其中6KB内存是用于SIMT函数调用参数传递的中转栈。如<a href="#%E4%BC%A0%E5%8F%82%E5%AF%84%E5%AD%98%E5%99%A8">传参寄存器</a>章节所述，硬件原生支持的函数间传参寄存器容量有限，当参数总大小超出该容量时，编译器会使用该中转栈空间完成参数传递，由此产生额外的访存开销，降低函数调用性能。因此，开发者应关注Device侧函数调用的参数规模，避免传递过大的参数对象。</p><h2 id="寄存器">寄存器<span id="section1137715201010"></span><a class="header-anchor" href="#寄存器">​</a></h2><p>寄存器是SIMT编程中最靠近计算单元、访问速度最高的存储资源，按功能可分为通用寄存器和传参寄存器，下文分别介绍。</p><h3 id="通用寄存器">通用寄存器<a class="header-anchor" href="#通用寄存器">​</a></h3><p>每个SIMT线程拥有独立的通用寄存器，生命周期与核函数（Kernel）一致，其分配由编译器统一管理，用于线程执行期间的局部数据存储。每个Vector Core（AIV）的SIMT通用寄存器文件总容量为128KB，由运行在该AIV上的线程块内所有线程按最大线程数划分使用。每个线程实际可用的寄存器数量取决于核函数（Kernel）定义时配置的最大线程数，最大线程数越大，每个线程可用寄存器越少，对应关系见下表。</p><p><strong>表1</strong> 最大线程数与每个线程可用寄存器数的对应关系</p><table><thead><tr><th>最大线程数</th><th>每个线程可用寄存器数</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table><p>由上表可知，最大线程数配置越大，每个线程可用的寄存器数量越少。若最大线程数配置过大且单线程计算逻辑复杂，编译器可能因寄存器资源不足，将部分局部变量或中间结果转存至GM上的SIMT通用栈空间，即寄存器溢出（register spill），从而引入额外的Global Memory访问并影响算子性能。开发者可通过<code>--cce-res-usage</code>编译选项查看核函数（Kernel）的寄存器资源使用情况，据此调整最大线程数或寄存器配置。</p><p>开发者可使用<a href="../../language_extension/simt_builtin_keywords.html#li23861114618">__launch_bounds__</a>配置最大线程数，间接控制每个线程的通用寄存器数量；也可使用<a href="../../language_extension/simt_builtin_keywords.html#section_maxnreg">__maxnreg__</a>直接配置每个线程的通用寄存器数量。</p><h3 id="传参寄存器">传参寄存器<a class="header-anchor" href="#传参寄存器">​</a></h3><p>传参寄存器专用于SIMT函数间的参数传递，去除内部占用后，用户可用的传参寄存器容量为<code>26 * 32bit</code>。当传递的参数总量超出该容量时，超出部分将溢出至栈空间，产生额外的寄存器到栈空间的数据搬运操作，降低算子性能，严重时可能导致栈溢出。因此，开发者应关注SIMT函数间传递参数的数据量，避免超出该限制。</p><h2 id="编程建议">编程建议<a class="header-anchor" href="#编程建议">​</a></h2><p>针对寄存器个数受限、栈空间有限容易引起性能劣化、甚至爆栈的问题，开发者可参考以下编程建议进行优化：</p><ul><li>尽量使用位宽较小的数据类型，因为通用寄存器位宽是32bit的，一个<code>int64_t</code>数据类型的变量，需要占用2个通用寄存器；</li><li>减少临时变量，能用地址引用的尽量不用临时变量，可减少寄存器的使用；</li><li>使用关键字<code>__inline__</code>修饰SIMT函数，编译器能够优化函数调用；</li><li>优化分支处理逻辑，减少Warp内的分支跳转；</li><li>对于复杂的结构体，可以规划UB或GM内存存放结构体数据，避免传参过大。</li></ul></article></div>`,1)])])}const v=a(e,[["render",i]]);export{m as __pageData,v as default};
